Map<String,Boolean> flags = new Map<String,Boolean>();
Map<String,Schema.SObjectField> fields = Account.SObjectType.getDescribe().fields.getMap();
Boolean personEnabled = fields.containsKey('IsPersonAccount');
Set<String> parts = new Set<String>{'Name','FirstName','LastName','MiddleName','Suffix'};
for (Schema.SObjectField token : fields.values()) {
    Schema.DescribeFieldResult field = token.getDescribe();
    if (field.isNameField() || parts.contains(field.getName())) flags.put(field.getName(), field.isNameField());
}
System.debug('ACCOUNT_NAME|'+JSON.serialize(new Map<String,Object>{'personAccounts'=>personEnabled,'flags'=>flags}));
